import java.util.*;

public class Main {
    ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        Set<ListNode> nodesInA = new HashSet<>();
        for (ListNode node = headA; node != null; node = node.next) nodesInA.add(node);   // remember every node object in list A
        for (ListNode node = headB; node != null; node = node.next) {
            if (nodesInA.contains(node)) return node;                                       // the first node from B also in A is the intersection
        }
        return null;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode common = new ListNode(8, new ListNode(4, new ListNode(5)));
        ListNode headA = new ListNode(4, new ListNode(1, common));
        ListNode headB = new ListNode(5, new ListNode(6, new ListNode(1, common)));
        ListNode result = solution.getIntersectionNode(headA, headB);
        System.out.println(result != null ? result.val : "null");
    }
}

