#include <bits/stdc++.h>
using namespace std;

ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) {
    unordered_set<ListNode*> nodesInA;
    for (ListNode* node = headA; node; node = node->next) nodesInA.insert(node);         // remember every node object in list A
    for (ListNode* node = headB; node; node = node->next) {
        if (nodesInA.count(node)) return node;                                             // the first node from B also in A is the intersection
    }
    return nullptr;
}

int main() {
    ListNode* common = new ListNode(8, new ListNode(4, new ListNode(5)));
    ListNode* headA = new ListNode(4, new ListNode(1, common));
    ListNode* headB = new ListNode(5, new ListNode(6, new ListNode(1, common)));
    ListNode* result = getIntersectionNode(headA, headB);
    cout << (result ? to_string(result->val) : "null") << endl;
    return 0;
}

