import java.util.*;

public class Main {
    ListNode getIntersectionNode(ListNode headA, ListNode headB) {
        ListNode pA = headA, pB = headB;
        while (pA != pB) {
            pA = (pA == null) ? headB : pA.next;                                    // once A's pointer runs out, redirect it to B's head
            pB = (pB == null) ? headA : pB.next;                                    // once B's pointer runs out, redirect it to A's head
        }
        return pA;                                                                    // they meet at the intersection, or both become null together
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode common = new ListNode(8, new ListNode(4, new ListNode(5)));
        ListNode headA = new ListNode(4, new ListNode(1, common));
        ListNode headB = new ListNode(5, new ListNode(6, new ListNode(1, common)));
        ListNode result = solution.getIntersectionNode(headA, headB);
        System.out.println(result != null ? result.val : "null");
    }
}

